insert into public.educational_articles (slug, category, title, summary, reading_minutes, body, sources, sort_order) values
  ('como-a-acne-se-forma', 'entendendo-a-acne', 'Como a acne se forma', 'Sebo, células mortas, bactérias e inflamação: os quatro processos que atuam juntos.', 4, '[{"paragraphs":["A acne começa dentro do folículo pilossebáceo — o “poro”. Cada folículo tem um pelo e uma glândula que produz sebo, a oleosidade natural da pele.","De forma simplificada, quatro processos costumam atuar juntos: mais produção de sebo (influência hormonal, especialmente a partir da puberdade), acúmulo de células mortas que formam um “tampão”, multiplicação da bactéria Cutibacterium acnes, que vive normalmente na pele, e inflamação."]},{"heading":"Os tipos de lesão","bullets":["Cravo aberto: ponto escuro. A cor vem da oxidação, não de sujeira.","Cravo fechado: pequena elevação clara.","Pápula: bolinha vermelha sem pus visível.","Pústula: lesão com ponto amarelado ou branco.","Nódulo e cisto: lesões profundas e doloridas, com maior risco de cicatriz — merecem avaliação de dermatologista."]},{"heading":"Fatores que podem contribuir","bullets":["Hormônios e genética (histórico familiar).","Produtos que obstruem poros (cremes pesados, alguns produtos capilares, maquiagem pesada).","Atrito e pressão: capacete, boné, alça de mochila, máscara.","Espremer e cutucar, que aumentam inflamação e risco de cicatriz.","Alguns medicamentos e condições de saúde — só um médico pode avaliar."],"note":"Acne não é falta de higiene. É uma condição da pele com várias causas, e o peso de cada uma muda de pessoa para pessoa."}]'::jsonb, '[{"label":"SBD — Acne: cuidados com a pele, como prevenir e tratamentos","url":"https://www.sbd.org.br/doencas/acne/"},{"label":"Ministério da Saúde (BVS) — Acne","url":"https://bvsms.saude.gov.br/acne/"},{"label":"AAD — How to treat different types of acne","url":"https://www.aad.org/public/diseases/acne/diy/types-breakouts"},{"label":"AAD — Acne scars: Causes","url":"https://www.aad.org/public/diseases/acne/derm-treat/scars/causes"}]'::jsonb, 0),
  ('pele-oleosa', 'entendendo-a-acne', 'Pele oleosa: cuidar sem agredir', 'Oleosidade não é acne, e tentar “secar” a pele à força costuma piorar.', 3, '[{"paragraphs":["Pele oleosa tem mais tendência a poros obstruídos, mas nem toda pele oleosa tem acne. A oleosidade também tem função: ajuda a proteger a pele."]},{"heading":"O que ajuda","bullets":["Lavar o rosto até duas vezes por dia e depois de suar, com limpador suave e a ponta dos dedos.","Escolher produtos “oil free” e “não comedogênicos”.","Usar hidratante leve depois da limpeza — sim, pele oleosa também precisa."]},{"heading":"O que costuma atrapalhar","bullets":["Esfregar a pele ou usar esfoliantes ásperos.","Lavar o rosto muitas vezes por dia.","Produtos com muito álcool, que ressecam e irritam.","Somar vários ácidos ao mesmo tempo: a AAD alerta que ácidos como salicílico, glicólico e lático podem ajudar, mas também podem ser agressivos demais."]}]'::jsonb, '[{"label":"AAD — How to control oily skin","url":"https://www.aad.org/public/everyday-care/skin-care-basics/dry/oily-skin"},{"label":"AAD — Face washing 101","url":"https://www.aad.org/public/everyday-care/skin-care-basics/care/face-washing-101"},{"label":"AAD — Acne: Tips for managing","url":"https://www.aad.org/public/diseases/acne/skin-care/tips"}]'::jsonb, 1),
  ('rotina-basica', 'rotina-de-cuidados', 'Rotina básica: manhã e noite', 'Limpar, hidratar e proteger de manhã. Remover, limpar, tratar (se houver) e hidratar à noite.', 4, '[{"heading":"Manhã","bullets":["Limpeza suave com água morna, sem esfregar.","Hidratante leve, oil free.","Protetor solar de amplo espectro, FPS 30 ou mais, em rosto, orelhas e pescoço."]},{"heading":"Noite","bullets":["Remover maquiagem e protetor, se usou.","Limpeza suave.","Tratamento indicado por profissional, se houver — na quantidade e frequência orientadas.","Hidratante leve."]},{"heading":"Regras de ouro","bullets":["Um produto novo de cada vez, com teste em pequena área antes.","Dar tempo: a AAD indica de 6 a 8 semanas de uso antes de avaliar um tratamento.","Ardência forte, vermelhidão intensa ou descamação excessiva são sinais para parar e buscar orientação."]}]'::jsonb, '[{"label":"AAD — Acne: Tips for managing","url":"https://www.aad.org/public/diseases/acne/skin-care/tips"},{"label":"AAD — 10 skin care habits that can worsen acne","url":"https://www.aad.org/public/diseases/acne/skin-care/habits-stop"},{"label":"AAD — Sunscreen FAQs","url":"https://www.aad.org/sun-protection/sunscreen-faqs"},{"label":"AAD — Face washing 101","url":"https://www.aad.org/public/everyday-care/skin-care-basics/care/face-washing-101"}]'::jsonb, 2),
  ('lendo-rotulos', 'ingredientes-e-rotulos', 'Como ler o rótulo de um produto', 'A frente da embalagem vende; a lista de ingredientes informa.', 4, '[{"bullets":["Termos como “purificante”, “detox” e “pele perfeita” não dizem o que o produto faz nem quanto contém de cada ingrediente.","No Brasil, a Anvisa exige a nomenclatura internacional INCI na rotulagem de cosméticos, e normas recentes passaram a exigir também os nomes traduzidos para o português.","Em geral, os ingredientes em maior quantidade aparecem primeiro — isso dá uma noção, mas não permite deduzir porcentagens."]},{"heading":"Termos comuns","bullets":["Não comedogênico: menor tendência a obstruir poros. Boa pista, não garantia.","Oil free: sem óleos na fórmula.","Dermatologicamente testado: passou por algum teste; não diz qual nem o resultado.","Hipoalergênico: formulado para reduzir o risco de alergia, não para eliminá-lo.","FPS: proteção contra UVB. Para UVA, procure “amplo espectro” ou “proteção UVA”."]}]'::jsonb, '[{"label":"Anvisa — Perguntas frequentes: RDC nº 646/2022 (rotulagem de ingredientes)","url":"https://www.gov.br/anvisa/pt-br/acessoainformacao/perguntasfrequentes/cosmeticos/rdc-no-646-2022"},{"label":"AAD — How to control oily skin","url":"https://www.aad.org/public/everyday-care/skin-care-basics/dry/oily-skin"},{"label":"AAD — Sunscreen FAQs","url":"https://www.aad.org/sun-protection/sunscreen-faqs"}]'::jsonb, 3),
  ('ingredientes', 'ingredientes-e-rotulos', 'Ingredientes comuns e seus cuidados', 'Ácido salicílico, peróxido de benzoíla, retinoides, niacinamida: o que cada um faz e onde mora o risco.', 5, '[{"note":"Visão geral, não indicação de uso. Concentração, fórmula e a sua pele mudam tudo."},{"heading":"Ácido salicílico","paragraphs":["Age dentro do poro ajudando a soltar células mortas. Aparece na diretriz de 2024 da AAD com recomendação condicional. Pode ressecar e irritar, principalmente somado a outros esfoliantes."]},{"heading":"Peróxido de benzoíla","paragraphs":["Reduz bactérias associadas à acne; tem recomendação forte na diretriz da AAD. Pode ressecar, irritar e descolorir toalhas, fronhas e roupas."]},{"heading":"Retinoides tópicos","paragraphs":["Atuam na renovação celular e têm recomendação forte na diretriz da AAD. No Brasil, retinoides como o adapaleno são medicamentos vendidos sob prescrição. Costumam irritar no início e aumentam a sensibilidade ao sol; exigem orientação médica, especialmente para quem está grávida ou planeja engravidar."]},{"heading":"Ácido azelaico","paragraphs":["Atua em obstrução, bactérias e inflamação. Recomendação condicional na diretriz da AAD. Pode arder levemente no início."]},{"heading":"Niacinamida","paragraphs":["Muito presente em produtos para pele oleosa e geralmente bem tolerada, mas com evidência específica para acne mais limitada que a dos ativos acima."]},{"heading":"Glicerina, ácido hialurônico e ceramidas","paragraphs":["Hidratam e apoiam a barreira da pele, ajudando a tolerar ativos que ressecam."]},{"heading":"Nunca no rosto","bullets":["Limão, pasta de dente, bicarbonato, álcool puro, óleos essenciais sem diluição e esfoliantes caseiros abrasivos. Podem irritar, manchar e queimar, sem evidência de benefício."]}]'::jsonb, '[{"label":"Reynolds RV et al. Guidelines of care for the management of acne vulgaris. J Am Acad Dermatol, 2024","url":"https://doi.org/10.1016/j.jaad.2023.12.017"},{"label":"AAD — How to treat different types of acne","url":"https://www.aad.org/public/diseases/acne/diy/types-breakouts"},{"label":"AAD — How to control oily skin","url":"https://www.aad.org/public/everyday-care/skin-care-basics/dry/oily-skin"},{"label":"SBD — Tratamento da acne","url":"https://www.sbd.org.br/tratamentos/tratamento-da-acne/"}]'::jsonb, 4),
  ('alimentacao', 'habitos-e-bem-estar', 'Alimentação e acne: o que se sabe', 'Há associação com dieta de alta carga glicêmica e leite, mas a evidência é limitada. Nenhum alimento cura acne.', 4, '[{"heading":"O que a pesquisa sugere","bullets":["Uma revisão sistemática de 2022 associou dietas de alta carga glicêmica a mais acne, com efeito descrito como modesto.","Um ensaio clínico de 2007 com 43 rapazes encontrou mais redução de lesões com dieta de baixa carga glicêmica — mas esse grupo também perdeu mais peso, o que confunde o resultado.","Uma meta-análise de 2018 com estudos observacionais associou laticínios, especialmente leite, a acne. Associação não é causa, e os autores apontam risco de viés."]},{"heading":"O que ainda é incerto","bullets":["Se mudar a alimentação, sozinha, melhora a acne de forma relevante para a maioria.","O papel de chocolate, gorduras e suplementos como whey.","A diretriz de 2024 da AAD considerou as evidências sobre dieta insuficientes para recomendações formais."]},{"heading":"Na prática","bullets":["Prefira um padrão alimentar variado a restrições. O Guia Alimentar do Ministério da Saúde é uma boa referência.","Não corte grupos de alimentos por conta própria por causa da acne.","Desconfie de chás, detox e suplementos vendidos como cura.","Se a comida estiver gerando ansiedade ou culpa, converse com um profissional de saúde."]}]'::jsonb, '[{"label":"AAD — Can the right diet get rid of acne?","url":"https://www.aad.org/public/diseases/acne/causes/diet"},{"label":"Meixiong J et al. Diet and acne: a systematic review. JAAD Int, 2022","url":"https://pubmed.ncbi.nlm.nih.gov/35373155/"},{"label":"Juhl CR et al. Dairy intake and acne vulgaris: meta-analysis. Nutrients, 2018","url":"https://pubmed.ncbi.nlm.nih.gov/30096883/"},{"label":"Smith RN et al. A low-glycemic-load diet improves symptoms in acne vulgaris patients. Am J Clin Nutr, 2007","url":"https://pubmed.ncbi.nlm.nih.gov/17616769/"},{"label":"Reynolds RV et al. Guidelines of care for the management of acne vulgaris. J Am Acad Dermatol, 2024","url":"https://doi.org/10.1016/j.jaad.2023.12.017"},{"label":"Ministério da Saúde — Guia alimentar para a população brasileira","url":"https://bvsms.saude.gov.br/bvs/publicacoes/guia_alimentar_populacao_brasileira_2ed.pdf"}]'::jsonb, 5),
  ('mitos-e-erros', 'mitos-e-verdades', 'Mitos e erros comuns', 'Espremer, esfregar, trocar de produto toda semana e outras armadilhas.', 3, '[{"heading":"Erros que atrapalham","bullets":["Espremer ou cutucar: aumenta inflamação e risco de cicatriz.","Esfregar a pele ou usar esfoliantes ásperos.","Trocar de produto toda semana, sem dar tempo para avaliar.","Usar vários ativos ao mesmo tempo.","Pular o protetor solar ou se bronzear para “secar” espinhas.","Aplicar o tratamento só na espinha, quando a orientação é cobrir a área com tendência."]},{"heading":"Mitos","bullets":["“Acne é falta de higiene.” Não é: começa dentro do poro.","“Pele oleosa não precisa de hidratante.” Precisa, em versão leve.","“Quanto mais arde, mais funciona.” Ardência forte é irritação.","“Natural não faz mal.” Óleos essenciais e extratos também irritam.","“Acne é coisa de adolescente.” Muitos adultos têm acne."]}]'::jsonb, '[{"label":"AAD — 10 skin care habits that can worsen acne","url":"https://www.aad.org/public/diseases/acne/skin-care/habits-stop"},{"label":"AAD — Acne scars: Causes","url":"https://www.aad.org/public/diseases/acne/derm-treat/scars/causes"},{"label":"AAD — Acne: Tips for managing","url":"https://www.aad.org/public/diseases/acne/skin-care/tips"}]'::jsonb, 6),
  ('quando-procurar-dermatologista', 'quando-procurar-dermatologista', 'Quando procurar um dermatologista', 'Acne profunda, dolorosa, persistente ou que deixa marcas merece avaliação profissional.', 3, '[{"heading":"Procure avaliação se","bullets":["Há espinhas profundas, grandes e doloridas (nódulos ou cistos).","A acne está deixando cicatrizes ou manchas.","Você manteve uma rotina por 6 a 8 semanas sem melhora.","A acne piorou de repente ou depois de começar um medicamento.","Há outros sinais, como menstruação muito irregular ou crescimento de pelos fora do comum.","Um produto causou reação forte.","A acne está afetando sua autoestima ou seu humor."]},{"heading":"Procure atendimento rápido se","bullets":["Houver inchaço importante, febre com lesões, reação alérgica forte ou dificuldade para respirar (neste caso, emergência)."]},{"heading":"Onde","bullets":["SUS: comece pela Unidade Básica de Saúde (UBS), que pode encaminhar ao dermatologista.","Rede privada: confirme o registro e a especialidade (RQE) do médico no site do CFM ou do CRM do seu estado."]}]'::jsonb, '[{"label":"AAD — Acne: Tips for managing","url":"https://www.aad.org/public/diseases/acne/skin-care/tips"},{"label":"AAD — Acne: Diagnosis and treatment","url":"https://www.aad.org/public/diseases/acne/derm-treat/treat"},{"label":"SBD — Tratamento da acne","url":"https://www.sbd.org.br/tratamentos/tratamento-da-acne/"},{"label":"AAD — Acne scars: Causes","url":"https://www.aad.org/public/diseases/acne/derm-treat/scars/causes"}]'::jsonb, 7),
  ('protetor-solar-no-dia-a-dia', 'rotina-de-cuidados', 'Protetor solar no dia a dia', 'O passo mais esquecido da rotina — e um dos mais importantes para quem tem acne.', 3, '[{"paragraphs":["A Academia Americana de Dermatologia recomenda protetor solar de amplo espectro (UVA e UVB), com FPS 30 ou mais e resistente à água, para todas as pessoas, de qualquer tom de pele.","Para quem tem acne, há um motivo a mais: o sol pode escurecer as manchas que ficam depois das espinhas, e alguns ingredientes usados em tratamentos aumentam a sensibilidade solar."]},{"heading":"Na prática","bullets":["Prefira versões não comedogênicas e de toque seco, se a pele for oleosa.","Aplique em quantidade suficiente em rosto, orelhas e pescoço.","Reaplique em exposição longa, depois de suar muito ou entrar na água.","Sombra, boné ou chapéu e roupas completam a proteção — o protetor sozinho não basta."],"note":"O melhor protetor é aquele que você gosta de usar todos os dias."}]'::jsonb, '[{"label":"AAD — Sunscreen FAQs","url":"https://www.aad.org/sun-protection/sunscreen-faqs"},{"label":"AAD — Acne: Tips for managing","url":"https://www.aad.org/public/diseases/acne/skin-care/tips"}]'::jsonb, 8),
  ('sono-estresse-e-suor', 'habitos-e-bem-estar', 'Sono, estresse, suor e atrito', 'Fatores do dia a dia que podem influenciar a pele — sem culpa e sem exagero.', 3, '[{"paragraphs":["A acne tem várias causas, e hábitos do dia a dia podem pesar mais para umas pessoas do que para outras. Observar com calma ajuda mais do que mudar tudo de uma vez."]},{"heading":"Suor e atrito","bullets":["Lave o rosto depois de suar, como orienta a AAD — principalmente sob capacete, boné ou máscara.","Alças de mochila, capacete e roupas apertadas podem favorecer lesões nas áreas de contato.","Cabelo oleoso encostando na testa também pode contribuir; lave com regularidade."]},{"heading":"Sono e estresse","paragraphs":["Muita gente percebe piora em fases de estresse ou pouco sono. Registrar isso no diário pode ajudar você a notar padrões — mas uma observação pessoal não prova causa e efeito."]}]'::jsonb, '[{"label":"AAD — Acne: Tips for managing","url":"https://www.aad.org/public/diseases/acne/skin-care/tips"},{"label":"AAD — 10 skin care habits that can worsen acne","url":"https://www.aad.org/public/diseases/acne/skin-care/habits-stop"},{"label":"SBD — Acne: cuidados com a pele, como prevenir e tratamentos","url":"https://www.sbd.org.br/doencas/acne/"}]'::jsonb, 9),
  ('acne-e-autoestima', 'habitos-e-bem-estar', 'Acne, autoestima e redes sociais', 'O impacto emocional da acne é real e merece atenção.', 2, '[{"paragraphs":["Acne pode afetar humor, vida social e confiança. Isso é legítimo — e é um dos motivos para procurar avaliação profissional, não um exagero.","Fotos editadas e filtros mostram uma pele que não existe. Textura, poros e marcas fazem parte de pele real."]},{"heading":"O que pode ajudar","bullets":["Comparar sua pele com ela mesma ao longo de semanas, não com fotos de outras pessoas.","Evitar se examinar com lupa ou contar espinhas todos os dias.","Buscar apoio psicológico se a acne estiver afetando muito como você se sente."]}]'::jsonb, '[{"label":"AAD — Acne: Diagnosis and treatment","url":"https://www.aad.org/public/diseases/acne/derm-treat/treat"},{"label":"SBD — Acne: cuidados com a pele, como prevenir e tratamentos","url":"https://www.sbd.org.br/doencas/acne/"}]'::jsonb, 10)
